const BASE_URL = "https://openzenith.pages.dev";

function latLonToTile(lat: number, lon: number, zoom: number): [number, number] {
  const n = 2 ** zoom;
  const x = Math.floor(((lon + 180) / 360) * n);
  const latRad = (lat * Math.PI) / 180;
  const y = Math.floor(((1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2) * n);
  return [x, y];
}

function tileToLatLon(x: number, y: number, zoom: number): { latMin: number; lonMin: number; latMax: number; lonMax: number } {
  const n = 2 ** zoom;
  const lonMin = (x / n) * 360 - 180;
  const lonMax = ((x + 1) / n) * 360 - 180;
  const latMaxRad = Math.atan(Math.sinh(Math.PI * (1 - (2 * y) / n)));
  const latMinRad = Math.atan(Math.sinh(Math.PI * (1 - (2 * (y + 1)) / n)));
  return {
    latMin: (latMinRad * 180) / Math.PI,
    lonMin,
    latMax: (latMaxRad * 180) / Math.PI,
    lonMax,
  };
}

export function TileDownloadTool({ dark, map }: Props) {
  const [dataset, setDataset] = useState(DATASETS[0].id);
  const [zMin, setZMin] = useState(5);
  const [zMax, setZMax] = useState(10);
  const [bbox, setBbox] = useState<{ latMin: number; lonMin: number; latMax: number; lonMax: number } | null>(null);
  const [tileCount, setTileCount] = useState(0);
  const [activeExample, setActiveExample] = useState("maplibre");
  const [drawing, setDrawing] = useState(false);
  const [drawStart, setDrawStart] = useState<{ x: number; y: number } | null>(null);
  const boxSourceRef = useRef<string | null>(null);
  const boxLayerRef = useRef<string | null>(null);

  const bg = dark ? "#0f0f0f" : "#fafafa";
  const cardBg = dark ? "#161616" : "#fff";
  const border = dark ? "#2a2a2a" : "#e5e5e5";
  const text = dark ? "#e5e5e5" : "#171717";
  const textSec = dark ? "#888" : "#666";
  const accent = "#22c55e";
  const codeBg = dark ? "#0d1117" : "#f6f8fa";

  const ds = DATASETS.find((d) => d.id === dataset) || DATASETS[0];

  // Calculate tile count when bbox or zoom changes
  useEffect(() => {
    if (!bbox) { setTileCount(0); return; }
    let total = 0;
    for (let z = zMin; z <= zMax; z++) {
      const [x1, y1] = latLonToTile(bbox.latMax, bbox.lonMin, z);
      const [x2, y2] = latLonToTile(bbox.latMin, bbox.lonMax, z);
      total += (x2 - x1 + 1) * (y2 - y1 + 1);
    }
    setTileCount(total);
  }, [bbox, zMin, zMax]);

  // Cleanup box layers on unmount
  useEffect(() => {
    return () => {
      try {
        if (map && boxSourceRef.current) {
          map.removeLayer(boxLayerRef.current!);
          map.removeSource(boxSourceRef.current);
        }
      } catch { /* map may be gone */ }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Draw bbox on map
  const updateBoxLayer = useCallback(
    (b: { latMin: number; lonMin: number; latMax: number; lonMax: number }) => {
      if (!map) return;
      const sourceId = "tile-download-box";
      const layerId = "tile-download-box-line";

      // Remove old
      try { map.removeLayer(layerId); } catch { /* ok */ }
      try { map.removeSource(sourceId); } catch { /* ok */ }

      const geojson = {
        type: "Feature" as const,
        geometry: {
          type: "Polygon" as const,
          coordinates: [
            [
              [b.lonMin, b.latMax],
              [b.lonMax, b.latMax],
              [b.lonMax, b.latMin],
              [b.lonMin, b.latMin],
              [b.lonMin, b.latMax],
            ],
          ],
        },
        properties: {},
      };

      map.addSource(sourceId, { type: "geojson", data: geojson });
      map.addLayer({
        id: layerId,
        type: "line",
        source: sourceId,
        paint: {
          "line-color": "#22c55e",
          "line-width": 2,
          "line-dasharray": [4, 2],
        },
      });
      boxSourceRef.current = sourceId;
      boxLayerRef.current = layerId;
    },
    [map],
  );

  // Use current map view as bbox
  const useCurrentView = useCallback(() => {
    if (!map) return;
    const bounds = map.getBounds();
    const b = { latMin: bounds.getSouth(), lonMin: bounds.getWest(), latMax: bounds.getNorth(), lonMax: bounds.getEast() };
    setBbox(b);
    updateBoxLayer(b);
  }, [map, updateBoxLayer]);

  // Draw mode handlers
  const handleMapClick = useCallback(
    (e: { lngLat: { lat: number; lng: number } }) => {
      if (!drawing) return;
      if (!drawStart) {
        setDrawStart({ x: e.lngLat.lng, y: e.lngLat.lat });
        return;
      }
      const b = {
        latMin: Math.min(drawStart.y, e.lngLat.lat),
        lonMin: Math.min(drawStart.x, e.lngLat.lng),
        latMax: Math.max(drawStart.y, e.lngLat.lat),
        lonMax: Math.max(drawStart.x, e.lngLat.lng),
      };
      setBbox(b);
      setDrawing(false);
      setDrawStart(null);
      updateBoxLayer(b);
    },
    [drawing, drawStart, updateBoxLayer],
  );

  const handleMouseMove = useCallback(
    (e: { lngLat: { lat: number; lng: number } }) => {
      if (!drawing || !drawStart || !map) return;
      const b = {
        latMin: Math.min(drawStart.y, e.lngLat.lat),
        lonMin: Math.min(drawStart.x, e.lngLat.lng),
        latMax: Math.max(drawStart.y, e.lngLat.lat),
        lonMax: Math.max(drawStart.x, e.lngLat.lng),
      };
      updateBoxLayer(b);
    },
    [drawing, drawStart, map, updateBoxLayer],
  );

  // Register map event handlers
  useEffect(() => {
    if (!map) return;
    const onClick = (e: any) => handleMapClick(e);
    const onMove = (e: any) => handleMouseMove(e);
    map.on("click", onClick);
    map.on("mousemove", onMove);
    return () => {
      map.off("click", onClick);
      map.off("mousemove", onMove);
    };
  }, [map, handleMapClick, handleMouseMove]);

  const clearBbox = useCallback(() => {
    setBbox(null);
    setDrawStart(null);
    if (map) {
      try { map.removeLayer(boxLayerRef.current!); } catch { /* ok */ }
      try { map.removeSource(boxSourceRef.current!); } catch { /* ok */ }
    }
  }, [map]);

  // Generate download script
  const generateScript = useCallback(
    (type: "bash" | "python") => {
      if (!bbox) return "";
      const tiles: string[] = [];
      for (let z = zMin; z <= zMax; z++) {
        const [x1, y1] = latLonToTile(bbox.latMax, bbox.lonMin, z);
        const [x2, y2] = latLonToTile(bbox.latMin, bbox.lonMax, z);
        for (let x = x1; x <= x2; x++) {
          for (let y = y1; y <= y2; y++) {
            tiles.push({ z, x, y });
          }
        }
      }

      if (type === "bash") {
        let script = `#!/bin/bash\n# OpenZenith Tile Downloader\n# Dataset: ${ds.label}\n# Region: [${bbox.latMin.toFixed(4)}, ${bbox.lonMin.toFixed(4)}] to [${bbox.latMax.toFixed(4)}, ${bbox.lonMax.toFixed(4)}]\n# Zoom: ${zMin}-${zMax} | Tiles: ${tiles.length}\n\nOUTDIR="tiles/${dataset}"\nmkdir -p "$OUTDIR"\n\nCOUNT=0\nTOTAL=${tiles.length}\n\nfor TILE in ${tiles.map((t) => `${t.z}/${t.x}/${t.y}`).join(" ")}; do\n  Z=$(echo "$TILE" | cut -d/ -f1)\n  X=$(echo "$TILE" | cut -d/ -f2)\n  Y=$(echo "$TILE" | cut -d/ -f3)\n  DIR="$OUTDIR/$Z/$X"\n  mkdir -p "$DIR"\n  FILE="$DIR/$Y.${ds.format}"\n  if [ ! -f "$FILE" ]; then\n    curl -sS -o "$FILE" "${BASE_URL}${ds.endpoint}/$Z/$X/$Y.${ds.format}"\n    COUNT=$((COUNT + 1))\n    if [ $((COUNT % 50)) -eq 0 ]; then\n      echo "Progress: $COUNT / $TOTAL"\n    fi\n  fi\ndone\n\necho "Done! Downloaded to $OUTDIR"\n`;
        return script;
      } else {
        let script = `#!/usr/bin/env python3
"""OpenZenith Tile Downloader

Dataset: ${ds.label}
Region: [${bbox.latMin.toFixed(4)}, ${bbox.lonMin.toFixed(4)}] to [${bbox.latMax.toFixed(4)}, ${bbox.lonMax.toFixed(4)}]
Zoom: ${zMin}-${zMax} | Tiles: ${tiles.length}
"""

tiles_str = tiles.map((t) => `    (${t.z}, ${t.x}, ${t.y}),`).join("\n");

        script += `import os
import urllib.request
from concurrent.futures import ThreadPoolExecutor, as_completed

BASE = "${BASE_URL}"
ENDPOINT = "${ds.endpoint}"
OUTDIR = "tiles/${dataset}"
EXT = "${ds.format}"

TILES = [
${tiles_str}
]

def download(z: int, x: int, y: int) -> tuple[str, bool]:
    path = os.path.join(OUTDIR, str(z), str(x), f"{y}.{EXT}")
    if os.path.exists(path):
        return path, False
    os.makedirs(os.path.dirname(path), exist_ok=True)
    url = f"{BASE}{ENDPOINT}/{z}/{x}/{y}.{EXT}"
    try:
        urllib.request.urlretrieve(url, path)
        return path, True
    except Exception as e:
        print(f"  Error {url}: {e}")
        return path, False

def main():
    print(f"Downloading {len(TILES)} tiles to {OUTDIR}/")
    downloaded = 0
    with ThreadPoolExecutor(max_workers=8) as pool:
        futures = {pool.submit(download, z, x, y): (z, x, y) for z, x, y in TILES}
        for i, fut in enumerate(as_completed(futures), 1):
            path, ok = fut.result()
            if ok:
                downloaded += 1
            if i % 50 == 0 or i == len(TILES):
                print(f"  Progress: {i}/{len(TILES)} ({downloaded} downloaded)")
    print(f"Done! {downloaded} new tiles saved to {OUTDIR}/")

if __name__ == "__main__":
    main()
`;
        return script;
      }
    },
    [bbox, zMin, zMax, dataset, ds],
  );

  const downloadScript = useCallback(
    (type: "bash" | "python") => {
      const script = generateScript(type);
      if (!script) return;
      const blob = new Blob([script], { type: "text/plain" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = type === "bash" ? "download_tiles.sh" : "download_tiles.py";
      a.click();
      URL.revokeObjectURL(url);
    },
    [generateScript],
  );

  const copyCode = useCallback((code: string) => {
    navigator.clipboard.writeText(code).then(() => {
      // Brief visual feedback handled by button text
    });
  }, []);

  const sizeEstimate = tileCount > 0 ? `~${(tileCount * 15 / 1024).toFixed(1)} MB` : "—";

  return (
    <div style={{ padding: 16, fontSize: 13, color: text }}>
      {/* Header */}
      <div style={{ marginBottom: 16 }}>
        <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 4 }}>Tile Downloader</div>
        <div style={{ fontSize: 11, color: textSec, lineHeight: 1.5 }}>
          Select a region on the map, choose a dataset and zoom levels, then download a script to fetch tiles locally.
        </div>
      </div>

      {/* Dataset selector */}
      <div style={{ marginBottom: 12 }}>
        <label style={{ fontSize: 11, fontWeight: 600, display: "block", marginBottom: 4 }}>Dataset</label>
        <select
          value={dataset}
          onChange={(e) => setDataset(e.target.value)}
          style={{
            width: "100%",
            padding: "6px 8px",
            borderRadius: 4,
            border: `1px solid ${border}`,
            background: cardBg,
            color: text,
            fontSize: 12,
          }}
        >
          {DATASETS.map((d) => (
            <option key={d.id} value={d.id}>
              {d.label}
            </option>
          ))}
        </select>
        <div style={{ fontSize: 10, color: textSec, marginTop: 2 }}>{ds.desc}</div>
      </div>

      {/* Zoom levels */}
      <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
        <div style={{ flex: 1 }}>
          <label style={{ fontSize: 11, fontWeight: 600, display: "block", marginBottom: 4 }}>Min Zoom</label>
          <input
            type="number"
            min={0}
            max={12}
            value={zMin}
            onChange={(e) => setZMin(Math.max(0, Math.min(12, parseInt(e.target.value) || 0)))}
            style={{
              width: "100%",
              padding: "6px 8px",
              borderRadius: 4,
              border: `1px solid ${border}`,
              background: cardBg,
              color: text,
              fontSize: 12,
            }}
          />
        </div>
        <div style={{ flex: 1 }}>
          <label style={{ fontSize: 11, fontWeight: 600, display: "block", marginBottom: 4 }}>Max Zoom</label>
          <input
            type="number"
            min={0}
            max={12}
            value={zMax}
            onChange={(e) => setZMax(Math.max(0, Math.min(12, parseInt(e.target.value) || 0)))}
            style={{
              width: "100%",
              padding: "6px 8px",
              borderRadius: 4,
              border: `1px solid ${border}`,
              background: cardBg,
              color: text,
              fontSize: 12,
            }}
          />
        </div>
      </div>

      {/* Region selection buttons */}
      <div style={{ marginBottom: 12 }}>
        <label style={{ fontSize: 11, fontWeight: 600, display: "block", marginBottom: 4 }}>Region</label>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
          <button
            onClick={useCurrentView}
            style={{
              padding: "5px 10px",
              borderRadius: 4,
              border: `1px solid ${border}`,
              background: cardBg,
              color: text,
              fontSize: 11,
              cursor: "pointer",
            }}
          >
            Use Current View
          </button>
          <button
            onClick={() => {
              if (drawing) {
                setDrawing(false);
                setDrawStart(null);
              } else {
                setDrawing(true);
                setDrawStart(null);
              }
            }}
            style={{
              padding: "5px 10px",
              borderRadius: 4,
              border: `1px solid ${drawing ? accent : border}`,
              background: drawing ? `${accent}22` : cardBg,
              color: drawing ? accent : text,
              fontSize: 11,
              cursor: "pointer",
            }}
          >
            {drawing ? "Cancel Draw" : "Draw on Map"}
          </button>
          {bbox && (
            <button
              onClick={clearBbox}
              style={{
                padding: "5px 10px",
                borderRadius: 4,
                border: `1px solid #ef4444`,
                background: "#ef444422",
                color: "#ef4444",
                fontSize: 11,
                cursor: "pointer",
              }}
            >
              Clear
            </button>
          )}
        </div>
        {drawing && (
          <div style={{ fontSize: 10, color: accent, marginTop: 4 }}>
            Click two points on the map to define a bounding box.
          </div>
        )}
      </div>

      {/* BBox info */}
      {bbox && (
        <div
          style={{
            padding: 10,
            borderRadius: 6,
            background: cardBg,
            border: `1px solid ${border}`,
            marginBottom: 12,
            fontSize: 11,
          }}
        >
          <div style={{ fontWeight: 600, marginBottom: 6 }}>Selected Region</div>
          <div style={{ fontFamily: "monospace", fontSize: 10, lineHeight: 1.6 }}>
            <div>
